package com.example.Email.Service;
import org.springframework.beans.factory.annotation.Value;import org.springframework.stereotype.Component;import javax.crypto.*;import javax.crypto.spec.*;import java.nio.charset.StandardCharsets;import java.security.*;import java.util.Base64;
@Component public class EmailTokenCipher {
 @Value("${email.token-encryption-key:}") private String encodedKey;
 public String encrypt(String value){if(value==null)return null;try{byte[] key=key();byte[] iv=new byte[12];SecureRandom.getInstanceStrong().nextBytes(iv);Cipher c=Cipher.getInstance("AES/GCM/NoPadding");c.init(Cipher.ENCRYPT_MODE,new SecretKeySpec(key,"AES"),new GCMParameterSpec(128,iv));byte[] out=c.doFinal(value.getBytes(StandardCharsets.UTF_8));byte[] all=new byte[iv.length+out.length];System.arraycopy(iv,0,all,0,iv.length);System.arraycopy(out,0,all,iv.length,out.length);return Base64.getEncoder().encodeToString(all);}catch(GeneralSecurityException e){throw new IllegalStateException("Unable to encrypt provider token.",e);}}
 public String decrypt(String value){if(value==null)return null;try{byte[] all=Base64.getDecoder().decode(value);byte[] iv=java.util.Arrays.copyOfRange(all,0,12);Cipher c=Cipher.getInstance("AES/GCM/NoPadding");c.init(Cipher.DECRYPT_MODE,new SecretKeySpec(key(),"AES"),new GCMParameterSpec(128,iv));return new String(c.doFinal(java.util.Arrays.copyOfRange(all,12,all.length)),StandardCharsets.UTF_8);}catch(GeneralSecurityException|IllegalArgumentException e){throw new IllegalStateException("Unable to decrypt provider token.",e);}}
 private byte[] key(){if(encodedKey==null||encodedKey.isBlank())throw new IllegalStateException("EMAIL_TOKEN_ENCRYPTION_KEY is required before connecting an email account.");byte[] k=Base64.getDecoder().decode(encodedKey);if(k.length!=32)throw new IllegalStateException("EMAIL_TOKEN_ENCRYPTION_KEY must be a Base64-encoded 32-byte key.");return k;}
}
